-- Synthetic schema-1 database created with product build 9a14ac4 (same product as bf7de22).
-- Authored original/translation, native prompt, fixed values, a oneoff and a real delegation.
-- This is previous product output, not a current-schema database with its version changed.
BEGIN TRANSACTION;
CREATE TABLE access_sessions(token_hash TEXT PRIMARY KEY,authority_hash TEXT NOT NULL);
CREATE TABLE app_metadata(key TEXT PRIMARY KEY,value TEXT NOT NULL);
INSERT INTO "app_metadata" VALUES('format','uimori-personal-v1');
CREATE TABLE assets (id TEXT PRIMARY KEY,chat_id TEXT NOT NULL REFERENCES chats(id),body TEXT NOT NULL,hash TEXT NOT NULL REFERENCES image_blobs(hash));
CREATE TABLE attempts (id TEXT PRIMARY KEY,chat_id TEXT REFERENCES chats(id),run_id TEXT REFERENCES runs(id),job_id TEXT REFERENCES jobs(id),role TEXT NOT NULL,connection_id TEXT NOT NULL,model_id TEXT NOT NULL,status TEXT NOT NULL,request TEXT NOT NULL,response TEXT,input_tokens INTEGER,output_tokens INTEGER,cost_usd REAL,raw_usage TEXT,price_revision TEXT,error TEXT);
CREATE TABLE author_note_commands(chat_id TEXT NOT NULL REFERENCES chats(id),request_key TEXT NOT NULL,command TEXT NOT NULL,result TEXT NOT NULL,PRIMARY KEY(chat_id,request_key));
CREATE TABLE author_note_heads(chat_id TEXT PRIMARY KEY REFERENCES chats(id),revision INTEGER NOT NULL);
CREATE TABLE author_notes(id TEXT PRIMARY KEY,chat_id TEXT NOT NULL REFERENCES chats(id),entry TEXT NOT NULL,retired_at TEXT,replaces_id TEXT REFERENCES author_notes(id));
CREATE TABLE branches (id TEXT PRIMARY KEY,chat_id TEXT NOT NULL REFERENCES chats(id),title TEXT NOT NULL,head_revision TEXT REFERENCES sources(id),revision INTEGER NOT NULL,is_default INTEGER NOT NULL);
INSERT INTO "branches" VALUES('main:ddf93dec-174e-465c-8eb2-117cb85da54d','ddf93dec-174e-465c-8eb2-117cb85da54d','기본 분기','a19ebfde-e72e-4075-aa8c-1e640dee0f0e',2,1);
CREATE TABLE chat_folders(id TEXT PRIMARY KEY,bot_id TEXT NOT NULL,title TEXT NOT NULL,default_persona TEXT,revision INTEGER NOT NULL CHECK(revision>0));
CREATE TABLE chat_lore_overrides(id TEXT PRIMARY KEY,chat_id TEXT NOT NULL REFERENCES chats(id),revision INTEGER NOT NULL,body TEXT NOT NULL,UNIQUE(chat_id,revision));
CREATE TABLE chat_lore_state(chat_id TEXT NOT NULL REFERENCES chats(id) ON DELETE CASCADE,branch_id TEXT NOT NULL REFERENCES branches(id) ON DELETE CASCADE,source_id TEXT NOT NULL REFERENCES sources(id) ON DELETE CASCADE,body TEXT NOT NULL,PRIMARY KEY(chat_id,branch_id));
CREATE TABLE chat_option_operations(id TEXT PRIMARY KEY,chat_id TEXT NOT NULL REFERENCES chats(id) ON DELETE CASCADE,request_id TEXT NOT NULL,command_hash TEXT NOT NULL,command TEXT NOT NULL,intent TEXT NOT NULL,result TEXT NOT NULL,created_at TEXT NOT NULL);
